// OTHVM Commands - deterministic slash-command bridge to the laptop MCP.
const envelope = $json || {};
const body = envelope.body || envelope;
const headers = envelope.headers || {};
const secret = 'REPLACE_WITH_COMMAND_SECRET';
const supplied = String(body.secret || headers['x-othvm-key'] || '');
if (supplied !== secret) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}
try {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://127.0.0.1:8765/tools/commands',
    headers: { 'Content-Type': 'application/json', 'X-API-Key': 'REPLACE_WITH_MCP_API_KEY' },
    body: {
      command: String(body.command || ''),
      args: String(body.args || ''),
      chat_id: String(body.chat_id || '')
    },
    json: true,
    timeout: 30000
  });
  return [{ json: r }];
} catch (e) {
  return [{ json: { ok: false, error: String((e && e.message) || e) } }];
}
